import type { Metadata } from "next";

import { site } from "@/lib/site";

// The share image from app/opengraph-image.png, generated by scripts/brand/build.py.
const shareImage = {
  url: "/opengraph-image.png",
  width: 1200,
  height: 630,
  alt: "NoOzyTech: simple, honest software for life and work",
};

/**
 * Metadata for one page: unique title and description, its own canonical
 * address, and complete social cards. Next.js merges metadata shallowly, so a
 * page's openGraph replaces the layout's whole object; this always returns
 * complete objects, including the share image, which would otherwise be
 * dropped along with the layout's openGraph (docs/engineering/seo.md).
 *
 * Leave out `title` on the home page: it uses the root layout's default.
 */
export function pageMetadata({
  title,
  description,
  path,
}: {
  title?: string;
  description: string;
  path: `/${string}`;
}): Metadata {
  return {
    ...(title && { title }),
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: site.name,
      locale: "en_US",
      url: path,
      description,
      images: [shareImage],
    },
    twitter: {
      card: "summary_large_image",
      description,
      images: [shareImage],
    },
  };
}
